package local_variables;

public class local_variables{
	
	
	
	public static void main(String[] args) {
		
		int i = 0;
		
		for(int j=0;j<3;j++) {
			
			i = i+j;
			
		}
		
		System.out.println(i+" - - - - "+j);
		
		
	}
}
